import styles from "./activity-row.module.less";
import Link from "@/core/components/primitives/link/link";
import { GatsbyImage } from "gatsby-plugin-image";
import { DateHelper, PlaceholderImageHelper } from "@/core/helpers";
import { buttonLinkIsInternal } from "@/core/components/primitives/parks-button/parks-button";
import { Translation } from "@/core/labels/i18n";
import { ActivityItemType, TimeItemType } from "@/core/components/primitives/daily-activity/daily-activity";
import { ContentfulEvent } from "@parksandresorts/webapiproxy-types";
import Icon, { IconName } from "@/core/components/primitives/icon/icon";
import { useTranslation } from "react-i18next";
import dayjs from "dayjs";
import { SpokenText } from "@/core/components/primitives/spoken-text/spoken-text";

const activityOpeningFormats = (activity: ContentfulEvent) => {
  const isActivityToday = DateHelper.isToday(activity.startDateAndTime);
  const startTime = activity.startDateAndTime && DateHelper.toStringTimeHHMM(activity.startDateAndTime);
  const endTime = activity.endDateAndTime && DateHelper.toStringTimeHHMM(activity.endDateAndTime);
  const isActivityAlreadyOpen = isActivityToday && DateHelper.hasTimePassedToday(startTime);
  const isActivityClosed = isActivityToday && endTime ? DateHelper.hasTimePassedToday(endTime) : false;

  return {
    isActivityToday,
    startTime,
    endTime,
    isActivityAlreadyOpen,
    isActivityClosed,
  };
};

export const getTimeStringForEvent = (
  event: ContentfulEvent,
  t: Translation,
): { timeString: string; contentfulLabel?: string } => {
  const { isActivityToday, startTime, endTime, isActivityAlreadyOpen, isActivityClosed } =
    activityOpeningFormats(event);

  if (isActivityToday) {
    if (isActivityAlreadyOpen && endTime && !isActivityClosed && !event.cancelled) {
      return { timeString: t("scheduleRowOpen") + " - " + endTime, contentfulLabel: "scheduleRowOpen" };
    }

    if (isActivityAlreadyOpen && !event.cancelled) {
      return { timeString: startTime };
    }
  }

  return { timeString: startTime + (endTime ? " - " + endTime : "") };
};

const TimePresenter = (content: ActivityItemTimePresenter | TimeItemTimePresenter) => {
  const { t } = useTranslation();
  const { endTime, isActivityAlreadyOpen, isActivityClosed } = activityOpeningFormats(content);

  const eventHasPassed = isActivityAlreadyOpen && (!endTime || isActivityClosed);
  const TextComponent = eventHasPassed ? "s" : "p";

  return (
    <div className={styles.timePresenter} data-cancelled={content.cancelled} data-has-passed={eventHasPassed}>
      {content.cancelled ? (
        <>
          <SpokenText text={t("scheduleRowCancelledSpokenText", { time: content.timeString })} />
          <s className={styles.timePresenterTime} aria-hidden>
            {content.timeString}
          </s>
          <TextComponent className={styles.cancelledText} data-contentful-label-id="scheduleRowCancelled" aria-hidden>
            {t("scheduleRowCancelled")}
          </TextComponent>
        </>
      ) : (
        <>
          {eventHasPassed && <SpokenText text={t("scheduleRowPassedSpokenText", { time: content.timeString })} />}
          <TextComponent
            className={styles.timePresenterTime}
            data-contentful-label-id={content.contentfulLabel}
            aria-hidden={eventHasPassed}
          >
            {content.timeString}
          </TextComponent>
        </>
      )}
    </div>
  );
};

const LocationLengthPresenter = ({ content }: { content: TimeItemType | ActivityItemType }) => {
  const { t } = useTranslation();
  const renderPresenter = (value: string, icon: IconName, label: string, contentfulLabelId: string) => {
    return (
      <div className={[styles.locationLength, "body-s"].join(" ")}>
        <Icon name={icon} className={styles.icon} />

        <p data-contentful-label-id={contentfulLabelId}>
          {label}: <b>{value}</b>
        </p>
      </div>
    );
  };

  return (
    <div className={styles.locationLengthWrapper}>
      {content?.location && renderPresenter(content.location, "location", t("location"), "location")}
      {content?.length && renderPresenter(content.length, "clock", t("length"), "length")}
    </div>
  );
};

export type TimeItemTimePresenter = ActivityItemTimePresenter & { timeLeftToEvent: number };
export type ActivityItemTimePresenter = ContentfulEvent & { timeString: string; contentfulLabel?: string };
export type ActivityItemsTimePresenter = Array<ActivityItemTimePresenter>;

const RowContent = (content: TimeItemType | ActivityItemType) => {
  const { t } = useTranslation();
  const getTimePresenterArray = (content: ActivityItemType): ActivityItemsTimePresenter | undefined => {
    const extendedEvents = content.events?.map((event) => {
      const { timeString, contentfulLabel } = getTimeStringForEvent(event, t);
      return {
        timeString,
        contentfulLabel,
        ...event,
      };
    });
    return extendedEvents;
  };

  const gatsbyImageData = content.image?.gatsbyImageData ?? content.imageInList?.gatsbyImageData;
  const fileUrl = content.image?.file?.url ?? content.imageInList?.file?.url;
  const fallbackImage = PlaceholderImageHelper.getPlaceholderImage("eventRow");
  const timePresenterArray =
    content.type === "dailyEventByActivity" && content.events ? getTimePresenterArray(content) : null;

  const timePresenter: TimeItemTimePresenter | null =
    content.type === "dailyEventByTime"
      ? {
          // The DateHelper function "minutesBeforeDate" is not applicable here, if we want a proper evaluation of the time left to the event.
          timeLeftToEvent: dayjs(content.event.startDateAndTime).diff(dayjs(), "seconds") / 60,
          ...getTimeStringForEvent(content.event, t),
          ...content.event,
        }
      : null;

  const TIME_LEFT_TO_EVENT_THRESHOLD = 60;

  const shouldShowTimeLeftToEvent =
    timePresenter?.timeLeftToEvent !== undefined &&
    timePresenter?.timeLeftToEvent >= -1 &&
    !timePresenter?.cancelled &&
    timePresenter?.timeLeftToEvent <= TIME_LEFT_TO_EVENT_THRESHOLD;

  return (
    <div className={styles.rowContent}>
      <div className={styles.imageWrapper}>
        {gatsbyImageData ? (
          <GatsbyImage className={styles.image} image={gatsbyImageData} alt={content.title} />
        ) : fileUrl ? (
          <img className={styles.image} src={fileUrl} alt={content.title} />
        ) : (
          <img className={styles.image} src={fallbackImage} alt={content.title} />
        )}
      </div>
      <div className={styles.borderPatternWrapper}>
        <div className={styles.borderPattern}></div>
      </div>
      <div className={styles.textWrapper}>
        <h5 className={styles.title}>{content.title}</h5>
        <p className={["body-m", styles.bodyText].join(" ")}>{content.shortDescriptionInList}</p>
        {(content?.location || content?.length) && <LocationLengthPresenter content={content} />}
        <div className={styles.timePresenterWrapper}>
          {content.type === "dailyEventByActivity" &&
            timePresenterArray?.map((timePresenter) => <TimePresenter key={timePresenter.id} {...timePresenter} />)}
          {content.type === "dailyEventByTime" && timePresenter && (
            <div className={styles.timePresenterContent}>
              <TimePresenter {...timePresenter} />
              {shouldShowTimeLeftToEvent && (
                <p className={styles.timeLeftToEvent} data-contentful-label-id="timeLeftToEvent">
                  {timePresenter?.timeLeftToEvent <= 0
                    ? // Present a temporary text when the activity has just begun.
                      t("startingNow")
                    : // Ceil the time that is left since it should be presented in minutes.
                      t("timeLeftToEvent", { count: Math.ceil(timePresenter.timeLeftToEvent) })}
                </p>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const ActivityRow = (content: TimeItemType | ActivityItemType) => {
  const url = content.showPageLink?.slug;

  if (url) {
    return (
      <Link
        internalLink={buttonLinkIsInternal(url) ? url : undefined}
        externalLink={buttonLinkIsInternal(url) ? undefined : url}
        className={styles.row}
        title={content.title}
      >
        <RowContent {...content} />
        <div className={styles.rightIconWrapper}>
          <Icon name="chevron-right" className={styles.rightIcon} />
        </div>
      </Link>
    );
  }

  return (
    <div className={[styles.row, styles.noLink].join(" ")}>
      <RowContent {...content} />
    </div>
  );
};

export default ActivityRow;
